const MAX_SAFE = Number.MAX_SAFE_INTEGER;

function assertInteger(value, name) {
  if (!Number.isInteger(value) || !Number.isSafeInteger(value)) {
    throw new TypeError(`${name} must be a safe integer, received ${value}`);
  }
}

function classRange(lo, hi) {
  if (lo === hi) return String(lo);
  return `[${lo}-${hi}]`;
}

function digitFor(count) {
  if (count === 0) return '';
  if (count === 1) return '\\d';
  return `\\d{${count}}`;
}

function buildSameLength(lo, hi) {
  if (lo === hi) return lo;
  const length = lo.length;
  if (lo === '0'.repeat(length) && hi === '9'.repeat(length)) {
    return digitFor(length);
  }
  let i = 0;
  while (lo[i] === hi[i]) i += 1;
  const prefix = lo.slice(0, i);
  const remaining = length - i - 1;
  const loDigit = Number(lo[i]);
  const hiDigit = Number(hi[i]);
  const loRest = lo.slice(i + 1);
  const hiRest = hi.slice(i + 1);
  const zeros = '0'.repeat(remaining);
  const nines = '9'.repeat(remaining);
  const branches = [];
  if (hiDigit - loDigit === 1) {
    branches.push(String(loDigit) + buildSameLength(loRest, nines));
    branches.push(String(hiDigit) + buildSameLength(zeros, hiRest));
