export function rangeToRegexSource(min, max, options = {}) {
  assertInteger(min, 'min');
  assertInteger(max, 'max');
  if (min < 0 || max < 0) throw new RangeError('only non-negative integers are supported');
  if (min > max) throw new RangeError(`min (${min}) must be <= max (${max})`);
  const chunks = splitByLength(min, max);
  const branches = chunks.map(([lo, hi]) => buildSameLength(String(lo), String(hi)));
  const body = branches.join('|');
  return branches.length === 1 ? body : '(?:' + body + ')';
}

export function rangeToRegex(min, max) {
  return new RegExp('^(?:' + rangeToRegexSource(min, max) + ')$');
}
```

